manifest.code:
apiVersion: apps/v1
kind: Deployment
metadata: { name: orders }
spec:
  replicas: 3
  selector: { matchLabels: { app: orders } }
  template:
    metadata: { labels: { app: orders } }
    spec:
      containers:
      - name: orders
        image: registry/orders:1.4.2      # never :latest in prod
        resources:
          requests: { cpu: "250m", memory: "512Mi" }   # scheduling
          limits:   { memory: "1Gi" }                  # OOMKill threshold
        readinessProbe:
          httpGet: { path: /actuator/health/readiness, port: 8080 }
        livenessProbe:
          httpGet: { path: /actuator/health/liveness, port: 8080 }
        envFrom:
        - configMapRef: { name: orders-config }
        - secretRef:    { name: orders-secrets }
